const makeNavLinksSmooth=()=>{const e=document.querySelectorAll("nav ul li a");e.forEach(e=>{e.addEventListener("click",o=>{o.preventDefault(),document.querySelector(e.hash).scrollIntoView({behavior:"smooth"})})})},navLinks={welcome:document.querySelector("#welcomeNav"),about:document.querySelector("#aboutNav"),portfolio:document.querySelector("#portfolioNav"),contact:document.querySelector("#contactNav")},observerOptions={root:null,rootMargin:"0px",threshold:.7},observerCallback=e=>{e.forEach(e=>{const o=navLinks[e.target.id];e.isIntersecting&&(o.classList.add("active"),Object.values(navLinks).forEach(e=>{e!==o&&e.classList.remove("active")}))})},observer=new IntersectionObserver(observerCallback,observerOptions);document.querySelectorAll("section").forEach(e=>observer.observe(e)),makeNavLinksSmooth();